// ------------------------------------------------------------- transport

/// How a call reaches the server.
enum Delivery {
  direct('direct'),
  optoSyncQueued('opto_sync_queued');

  const Delivery(this.wire);

  final String wire;
}

/// Where a queued call's opto-sync record id comes from.
enum RecordIdFrom {
  path, request, minted;
}

/// Static description of a queued call's opto-sync binding.
class OptoSyncBinding {
  const OptoSyncBinding({required this.table, required this.operation, required this.from, this.name});

  final String table;
  final String operation;
  final RecordIdFrom from;
  final String? name;
}

/// One outbound call, fully resolved. Transports never re-derive paths.
class RpcRequest {
  const RpcRequest({
    required this.key,
    required this.method,
    required this.path,
    required this.pathTemplate,
    this.query = const [],
    this.body,
    this.delivery = Delivery.direct,
    this.optoSync,
  });

  final String key;
  final String method;

  /// Path with every parameter already substituted and encoded.
  final String path;

  /// The unsubstituted template, so a transport can locate a named
  /// parameter inside [path] instead of guessing at its position.
  final String pathTemplate;
  final List<MapEntry<String, String>> query;

  /// JSON body, or null for operations that carry none.
  final String? body;
  final Delivery delivery;
  final OptoSyncBinding? optoSync;
}

/// The single seam between generated code and the network.
///
/// Implement it over HTTP for direct calls and over an opto-sync queue for
/// queued ones. The dependency runs one way: this library calls opto-sync,
/// never the reverse.
abstract interface class RpcTransport {
  Future<String> call(RpcRequest request);
}

/// Encode one path segment so an id containing `/` cannot reshape the URL.
String encodeSegment(String value) => Uri.encodeComponent(value);

String _queryValue(Object? value) => value is String ? value : '$value';

// ------------------------------------------------------------- operations

/// `GET /healthz`
String healthzPath() => "/healthz";

/// `POST /v1/matters`
String createMatterPath() => "/v1/matters";

/// `GET /v1/matters/{id}`
String getMatterPath(MatterId id) =>
  '/v1/matters/${encodeSegment('$id')}';

/// `POST /v1/matters/{id}/walk`
String walkMatterPath(MatterId id) =>
  '/v1/matters/${encodeSegment('$id')}/walk';

/// `GET /v1/matters/{id}/documents`
String getDocumentsPath(MatterId id) =>
  '/v1/matters/${encodeSegment('$id')}/documents';

/// `GET /v1/matters/{id}/facts`
String getFactsPath(MatterId id) =>
  '/v1/matters/${encodeSegment('$id')}/facts';

/// `GET /v1/avenues`
String avenuesPath() => "/v1/avenues";

/// `GET /v1/geography`
String geographyPath() => "/v1/geography";

/// `POST /pmap.v1.Interview/CheckFieldSanity`
String checkFieldSanityPath() => "/pmap.v1.Interview/CheckFieldSanity";

/// `POST /pmap.v1.Interview/AskCounsel`
String askCounselPath() => "/pmap.v1.Interview/AskCounsel";

/// `POST /v1/fields/sanity`
String checkFieldSanityRestPath() => "/v1/fields/sanity";

Future<String> healthz(RpcTransport transport) async {
  final path = healthzPath();
  const query = <MapEntry<String, String>>[];
  final raw = await transport.call(RpcRequest(
    key: "healthz",
    method: "GET",
    path: path,
    pathTemplate: "/healthz",
    query: query,
    delivery: Delivery.direct,
  ));
  return jsonDecode(raw) as String;
}

