/// One row per declared operation.
class OperationInfo {
  const OperationInfo({required this.key, required this.path, required this.methods, required this.delivery});

  final String key;
  final String path;
  final List<String> methods;
  final Delivery delivery;
}

/// Every operation in the route map, in declaration order.
const List<OperationInfo> operations = [
  OperationInfo(key: "healthz", path: "/healthz", methods: ["GET"], delivery: Delivery.direct),
  OperationInfo(key: "create_matter", path: "/v1/matters", methods: ["POST"], delivery: Delivery.direct),
  OperationInfo(key: "get_matter", path: "/v1/matters/{id}", methods: ["GET"], delivery: Delivery.direct),
  OperationInfo(key: "walk_matter", path: "/v1/matters/{id}/walk", methods: ["POST"], delivery: Delivery.optoSyncQueued),
  OperationInfo(key: "get_documents", path: "/v1/matters/{id}/documents", methods: ["GET"], delivery: Delivery.direct),
  OperationInfo(key: "get_facts", path: "/v1/matters/{id}/facts", methods: ["GET"], delivery: Delivery.direct),
  OperationInfo(key: "avenues", path: "/v1/avenues", methods: ["GET"], delivery: Delivery.direct),
  OperationInfo(key: "geography", path: "/v1/geography", methods: ["GET"], delivery: Delivery.direct),
  OperationInfo(key: "CheckFieldSanity", path: "/pmap.v1.Interview/CheckFieldSanity", methods: ["POST"], delivery: Delivery.direct),
  OperationInfo(key: "AskCounsel", path: "/pmap.v1.Interview/AskCounsel", methods: ["POST"], delivery: Delivery.direct),
  OperationInfo(key: "check_field_sanity_rest", path: "/v1/fields/sanity", methods: ["POST"], delivery: Delivery.direct),
];

/// Operations that route through opto-sync's durable queue.
